from datetime import datetime

from pydantic import BaseModel, ConfigDict, Field

from app.models.course import DifficultyLevel
from app.models.flashcard import MasteryStatus

# =============================================================================
# Gemini AI Structured Output Schemas
# =============================================================================


class AIGeneratedCard(BaseModel):
    """Structured individual card generated by Gemini."""

    model_config = ConfigDict(extra="ignore")

    front: str = Field(..., description="Active recall prompt, question, or problem")
    back: str = Field(..., description="Concise, authoritative answer or explanation")
    hint: str | None = Field(
        default=None, description="Memory jogger clue without revealing answer"
    )
    key_concept: str | None = Field(default=None, description="2 to 4 word conceptual category")


class AIGeneratedDeckPayload(BaseModel):
    """Structured deck payload returned by Gemini LLM."""

    model_config = ConfigDict(extra="ignore")

    title: str = Field(..., description="Engaging, topic-specific deck title")
    description: str = Field(..., description="High-level description of concepts covered")
    topic: str = Field(..., description="Subject or technical topic")
    cards: list[AIGeneratedCard] = Field(..., min_length=1, description="List of synthesized cards")


# =============================================================================
# Client Request & Response Schemas
# =============================================================================


class FlashcardCreate(BaseModel):
    """Payload to create an individual flashcard."""

    model_config = ConfigDict(extra="forbid")

    front: str = Field(..., min_length=2, max_length=2000, description="Front prompt/question")
    back: str = Field(..., min_length=2, max_length=4000, description="Back answer/explanation")
    hint: str | None = Field(default=None, max_length=500, description="Optional hint")
    key_concept: str | None = Field(default=None, max_length=100, description="Category tag")


class FlashcardUpdate(BaseModel):
    """Payload to update an individual flashcard."""

    model_config = ConfigDict(extra="forbid")

    front: str | None = Field(default=None, min_length=2, max_length=2000)
    back: str | None = Field(default=None, min_length=2, max_length=4000)
    hint: str | None = Field(default=None, max_length=500)
    key_concept: str | None = Field(default=None, max_length=100)


class FlashcardResponse(BaseModel):
    """Public representation of an active recall card."""

    model_config = ConfigDict(from_attributes=True)

    id: str
    deck_id: str
    front: str
    back: str
    hint: str | None
    key_concept: str | None
    box: int
    review_count: int
    correct_count: int
    last_reviewed_at: datetime | None
    mastery_status: MasteryStatus
    created_at: datetime


class FlashcardDeckCreate(BaseModel):
    """Payload for manual flashcard deck authoring."""

    model_config = ConfigDict(extra="forbid")

    title: str = Field(..., min_length=2, max_length=200, description="Deck title")
    topic: str = Field(..., min_length=2, max_length=100, description="Primary technical topic")
    description: str | None = Field(default=None, max_length=1000, description="Deck overview")
    lesson_id: str | None = Field(default=None, description="Optional associated lesson ID")
    is_public: bool = Field(default=False, description="Whether deck is discoverable by peers")
    cards: list[FlashcardCreate] = Field(default=[], description="Initial card list")


class FlashcardDeckUpdate(BaseModel):
    """Payload to modify flashcard deck metadata."""

    model_config = ConfigDict(extra="forbid")

    title: str | None = Field(default=None, min_length=2, max_length=200)
    topic: str | None = Field(default=None, min_length=2, max_length=100)
    description: str | None = Field(default=None, max_length=1000)
    is_public: bool | None = None


class FlashcardDeckResponse(BaseModel):
    """Deck summary with Leitner mastery distribution stats."""

    model_config = ConfigDict(from_attributes=True)

    id: str
    user_id: str
    lesson_id: str | None
    title: str
    description: str | None
    topic: str
    card_count: int
    is_public: bool
    mastered_count: int = Field(default=0, description="Cards in Leitner boxes 4-5")
    learning_count: int = Field(default=0, description="Cards in Leitner boxes 2-3")
    new_count: int = Field(default=0, description="Cards in Leitner box 1 / unreviewed")
    created_at: datetime
    updated_at: datetime


class FlashcardDeckDetailResponse(FlashcardDeckResponse):
    """Full deck details including all contained flashcards."""

    cards: list[FlashcardResponse] = Field(default=[], description="All deck cards")


class AIGenerateDeckRequest(BaseModel):
    """Request payload to generate a flashcard deck via Gemini."""

    model_config = ConfigDict(extra="forbid")

    topic: str = Field(..., min_length=2, max_length=150, description="Subject or technical topic")
    num_cards: int = Field(default=5, ge=2, le=20, description="Target card count (2 to 20)")
    difficulty: DifficultyLevel = Field(
        default=DifficultyLevel.INTERMEDIATE,
        description="Depth and rigor level",
    )
    lesson_id: str | None = Field(default=None, description="Optional lesson ID to ground content")
    custom_instructions: str | None = Field(
        default=None,
        max_length=1000,
        description="Optional focal themes or exam directives",
    )


class CardReviewSubmission(BaseModel):
    """Individual card recall self-assessment in a study session."""

    model_config = ConfigDict(extra="forbid")

    card_id: str = Field(..., description="Flashcard ID being reviewed")
    rating: int = Field(
        ...,
        ge=1,
        le=4,
        description="Leitner rating: 1=Again (Reset), 2=Hard, 3=Good (+1 Box), 4=Easy (+2 Boxes)",
    )


class StudySessionSubmission(BaseModel):
    """Batch submission of flashcard reviews from a study session."""

    model_config = ConfigDict(extra="forbid")

    reviews: list[CardReviewSubmission] = Field(
        ...,
        min_length=1,
        max_length=50,
        description="List of card reviews",
    )


class CardReviewResult(BaseModel):
    """Result of an individual flashcard review evaluation."""

    card_id: str
    previous_box: int
    new_box: int
    is_promoted: bool
    new_mastery_status: MasteryStatus


class StudySessionResponse(BaseModel):
    """Feedback and XP reward summary for completed flashcard study session."""

    deck_id: str
    total_reviewed: int
    promoted_count: int
    demoted_count: int
    newly_mastered_count: int
    xp_awarded: int
    results: list[CardReviewResult]
